class EvenRange implements Iterable<Integer> {
    private int n;
    EvenRange(int n) { this.n = n; }
    public Iterator<Integer> iterator() { return new It(); }
    private class It implements Iterator<Integer> {   // inner: sees n
        private int cur = 0;                           // position lives in the iterator
        public boolean hasNext() { return cur < n; }
        public Integer next() { int r = cur; cur += 2; return r; }
    }
}

// Yields the items of an IntList that are <= the list's first item.
class LEQIterator implements Iterator<Integer> {
    private IntList p;
    private int bound;
    LEQIterator(IntList L) {
        p = L;
        bound = (L == null) ? 0 : L.first;
        advance();
    }
    private void advance() { while (p != null && p.first > bound) p = p.rest; }
    public boolean hasNext() { return p != null; }
    public Integer next() {
        if (!hasNext()) throw new NoSuchElementException();
        int r = p.first;
        p = p.rest;
        advance();
        return r;
    }
}

class BSTIter implements Iterator<Integer> {
    private Deque<Node> st = new ArrayDeque<>();
    BSTIter(Node root) { pushLeft(root); }
    private void pushLeft(Node n) { while (n != null) { st.push(n); n = n.left; } }
    public boolean hasNext() { return !st.isEmpty(); }
    public Integer next() {
        Node n = st.pop();
        pushLeft(n.right);      // the successor chain
        return n.key;
    }
}

