class Grid implements Iterator<Integer> {
    private int[][] g; private int r = 0, c = 0;
    Grid(int[][] g) { this.g = g; skip(); }
    private void skip() {                     // move to a valid (r, c) or r == g.length
        while (r < g.length && c >= g[r].length) { r++; c = 0; }
    }
    public boolean hasNext() { return r < g.length; }
    public Integer next() {
        int x = g[r][c];
        c++;
        skip();
        return x;
    }
}

class Judge<T extends Comparable<T>> implements Comparator<T>, Iterable<T> {
    private List<T> winners = new ArrayList<>();
    public int compare(T a, T b) {
        int c = a.compareTo(b);
        if (c > 0) winners.add(a);
        else if (c < 0) winners.add(b);
        return c;
    }
    public Iterator<T> iterator() { return winners.iterator(); }
}

private int degreeLen() {                 // length without trailing zeros
    int n = coef.length;
    while (n > 0 && coef[n - 1] == 0) n--;
    return n;
}
@Override public boolean equals(Object o) {
    if (this == o) return true;
    if (!(o instanceof Poly p)) return false;
    int n = degreeLen();
    if (n != p.degreeLen()) return false;
    for (int i = 0; i < n; i++) if (coef[i] != p.coef[i]) return false;
    return true;
}
@Override public int hashCode() {
    int h = 0, n = degreeLen();
    for (int i = 0; i < n; i++) h = 31 * h + coef[i];
    return h;
}

