class PeekIterator<T> implements Iterator<T> {
    private Iterator<T> it; private T buf; private boolean full = false;
    PeekIterator(Iterator<T> it) { this.it = it; }
    public T peek() {
        if (!full) { buf = it.next(); full = true; }   // NoSuchElement if empty
        return buf;
    }
    public boolean hasNext() { return full || it.hasNext(); }
    public T next() {
        if (full) { full = false; return buf; }
        return it.next();
    }
}
